  private void changeCurrentRoot(@Nullable final SNodeId rootId) {
    if (myMergeRootsPane != null && myRootId == rootId) {
      return;
    }
    applyMetadataChanges();

    if (myMergeRootsPane != null && (myRootId == null && rootId != null || myRootId != null && rootId == null)) {
      // XXX quite odd way to re-initialize MergeRootsPane the moment we switch to or from 'model properties' node, which
      //    resided in another repo and hence can't re-use DiffEditors of existing MergeRootsPane
      discardMergeRootPane();
    }
    myRootId = rootId;
    final MergeSession session = (rootId == null ? myMetadataMergeSession : myMergeSession);
    myProjectRepository.getModelAccess().runReadAction(() -> {
      SNodeId nodeId = (rootId == null ? MetadataUtil.getMetadataRootId() : rootId);
      if (myMergeRootsPane == null) {
        myMergeRootsPane = new MergeRootsPane(myProject, session, nodeId, myMergeTree.getNameForRoot(rootId), myContentTitles, myTitleCustomizers, () -> trackMovedNodes());
        DefaultActionGroup actionGroup = new DefaultActionGroup();
        actionGroup.addAll(myMergeRootsPane.getActions());
        ActionToolbar toolbar = ActionManager.getInstance().createActionToolbar(ActionPlaces.TOOLBAR, actionGroup, true);
        toolbar.setTargetComponent(myMergeRootsPane.getPanel());
        myMergeRootsPane.registerShortcuts(MergeModelsPanel.this);
        JPanel panel = new JPanel(new BorderLayout());
        panel.add(toolbar.getComponent(), BorderLayout.NORTH);
        panel.add(myMergeRootsPane.getPanel(), BorderLayout.CENTER);
        myPanel.setSecondComponent(panel);
      } else {
        myMergeRootsPane.setRoodId(nodeId, session);
      }
    });
  }

